  'data.glossary.123.description': 'style: percentage_damage / element: e.none\n魔法攻擊次數達20次以上時發動。造成對方剩餘HP的2/5固定傷害（無視魔法防禦力）',
  'data.glossary.2_1_9.subtitle': '求. 支線任務（達成條件可獲得結晶作為報酬）',
